/* ---------- розділи ---------- */
const SEC_LIST=[
 {id:'terms',t:'Терміни та загальні положення',sh:'Терміни',ic:['sq','і']},
 {id:'duties',t:'Обов’язки водія',sh:'Обов’язки водія',ic:['sq','✓']},
 {id:'signals',t:'Світлофор і регулювальник',sh:'Сигнали',ic:['light']},
 {id:'signs',t:'Дорожні знаки',sh:'Знаки',ic:['tri','!']},
 {id:'marking',t:'Дорожня розмітка',sh:'Розмітка',ic:['mark']},
 {id:'maneuver',t:'Маневрування і розташування',sh:'Маневрування',ic:['blue','↱']},
 {id:'speed',t:'Швидкість, обгін, дистанція',sh:'Швидкість і обгін',ic:['circ','50']},
 {id:'roads',t:'Автомагістралі, житлові зони, гірські дороги',sh:'Особливі дороги',ic:['motorway']},
 {id:'stop',t:'Зупинка і стоянка',sh:'Зупинка і стоянка',ic:['nostop']},
 {id:'cross',t:'Проїзд перехресть',sh:'Перехрестя',ic:['dia']},
 {id:'ped',t:'Пішоходи, переїзди, спецтранспорт',sh:'Пішоходи і переїзди',ic:['ped']},
 {id:'bikes',t:'Велосипедисти та гужовий транспорт',sh:'Велосипедисти',ic:['bike']},
 {id:'light',t:'Світлові прилади і буксирування',sh:'Світло і буксирування',ic:['blue','☀']},
 {id:'cargo',t:'Перевезення пасажирів і вантажів',sh:'Перевезення',ic:['truck']},
 {id:'tech',t:'Технічний стан і номерні знаки',sh:'Техстан',ic:['tire']},
 {id:'safety',t:'Безпека і домедична допомога',sh:'Безпека і допомога',ic:['aid']}
];
const SEC={}; SEC_LIST.forEach(s=>SEC[s.id]=s);

/* ---------- питання (перший варіант — правильний, на екрані перемішуються) ---------- */
const QB=[];
function q(id,s,text,o,e,sign){QB.push({id,s,q:text,o,e,sign:sign||null});}

/* Терміни та загальні положення */
q('t1','terms','Що таке обгін?',['Випередження одного або кількох ТЗ із виїздом на смугу зустрічного руху','Будь-яке випередження ТЗ, що їде попереду','Перестроювання в сусідню смугу попутного напрямку'],'Обгін — це саме випередження з виїздом на зустрічну смугу. Якщо обганяєш у межах своїх смуг, це просто випередження.');
q('t2','terms','Скільки триває зупинка за ПДР?',['До 5 хвилин, або довше, якщо це потрібно для посадки чи висадки пасажирів або вантажу','До 10 хвилин з будь-якої причини','До 1 хвилини'],'Якщо стоїш понад 5 хвилин з причин, не пов’язаних з посадкою, висадкою чи вантажем, — це вже стоянка.');
q('t3','terms','Що ПДР називає недостатньою видимістю?',['Видимість дороги менше 300 м у темряві, тумані, дощ чи снігопад','Видимість менше 100 м через поворот або підйом','Будь-яку видимість менше 50 м'],'Недостатня видимість — через погоду або темряву. Коли огляд закриває рельєф, поворот чи будівлі, це обмежена оглядовість.');
q('t4','terms','Чи вважається перехрестям виїзд з двору, парковки чи АЗС?',['Ні, виїзди з прилеглих територій — не перехрестя','Так, якщо на виїзді стоїть знак пріоритету','Так, завжди'],'Це прилегла територія. Виїжджаючи з неї, ти поступаєшся і пішоходам, і всім ТЗ на дорозі.');
q('t5','terms','Де проходить межа перехрестя?',['Уявні лінії між початком заокруглень країв проїжджої частини','По стоп-лінії','Там, де стоять знаки пріоритету'],'Перехрестя починається там, де починаються заокруглення країв проїжджої частини.');
q('t6','terms','Що таке темна пора доби?',['Час від кінця вечірніх сутінків до початку ранкових','Час з 22:00 до 6:00','Час від заходу до сходу сонця'],'Сутінки ще не темна пора. Вона починається, коли вечірні сутінки закінчились.');
q('t7','terms','Хто, крім людини за кермом, теж вважається водієм?',['Інструктор, який навчає керування, перебуваючи в цьому ТЗ','Пасажир на передньому сидінні','Власник авто, який сидить поруч'],'Водієм вважається і той, хто навчає керування, перебуваючи безпосередньо в автомобілі.');
q('t8','terms','Яка мінімальна ширина смуги руху за ПДР?',['2,75 м','2,5 м','3,5 м'],'Смуга руху — поздовжня смуга завширшки щонайменше 2,75 м для руху в один ряд, з розміткою або без неї.');
q('t9','terms','Який рух транспортних засобів установлено в Україні?',['Правосторонній','Лівосторонній','Залежить від розмітки на конкретній дорозі'],'В Україні рух транспортних засобів правосторонній (п. 1.2).');
q('t10','terms','З причепа на дорогу висипався вантаж і заважає руху. Що потрібно зробити за ПДР?',['Усунути перешкоду, а якщо не вдається — попередити інших і повідомити поліцію чи власника дороги','Їхати далі: прибирати проїзну частину має дорожня служба, водій тут ні до чого','Лише сфотографувати місце й повідомити свою страхову компанію про пригоду'],'Хто створив перешкоду, мусить негайно подбати про безпеку на цій ділянці й усунути її, а якщо не може — попередити інших і повідомити поліцію або власника дороги (п. 1.5).');
q('t11','terms','До яких учасників руху водії зобов’язані бути особливо уважними?',['До велосипедистів, осіб у кріслах колісних і пішоходів','До водіїв вантажівок, автобусів і тракторів','До водіїв зі стажем менше двох років'],'А до дітей, людей похилого віку й осіб з явними ознаками інвалідності всі учасники руху мають бути особливо обережними (п. 1.7).');
q('t12','terms','Автомобіль для перевезення пасажирів має 9 місць для сидіння разом з місцем водія. Що це за ПДР?',['Легковий автомобіль','Мікроавтобус','Автобус'],'Легковий — не більше дев’яти місць для сидіння з місцем водія включно. Автобус, зокрема мікроавтобус, — більше дев’яти (п. 1.10).');
q('t13','terms','Мікроавтобус — це одноповерховий автобус, у якому місць для сидіння разом з місцем водія…',['Не більше сімнадцяти','Не більше дев’яти','Не більше двадцяти чотирьох'],'Мікроавтобус — одноповерховий автобус з кількістю місць для сидіння не більше 17 з місцем водія включно (п. 1.10).');
q('t14','terms','Що з переліченого — обов’язкова ознака автомагістралі за ПДР?',['Окремі проїзні частини для кожного напрямку, розділені розділювальною смугою','Щонайменше три смуги руху в кожному напрямку та широкі узбіччя','Цілодобове штучне освітлення й аварійні телефони на всьому протязі'],'Ще ознаки: немає перетинів на одному рівні з дорогами, коліями й доріжками, є огородження й сітка, дорогу позначено знаком 5.1 (п. 1.10).');
q('t15','terms','Що з цього НЕ вважається дорогою за ПДР?',['Довільно накатана колія через поле','Спеціально побудована тимчасова об’їзна дорога','Міст разом із тротуарами на ньому'],'Дорога включає розташовані на ній споруди і спеціально побудовані тимчасові дороги, але не довільно накатані колії (п. 1.10).');
q('t16','terms','Що ПДР називає автопоїздом (транспортним составом)?',['Механічний ТЗ, з’єднаний з одним або кількома причепами зчіпним пристроєм','Два автомобілі, з’єднані буксирним тросом','Колону з трьох і більше вантажівок, що їдуть разом'],'Автопоїзд — це тягач з причепом (причепами) на зчіпному пристрої. Перевезення несправного авто на тросі — буксирування (п. 1.10).');
q('t17','terms','Безпечна дистанція має дати змогу уникнути зіткнення, якщо авто попереду раптово загальмує. Як саме?',['Не здійснюючи жодного маневру','Об’їхавши його по сусідній смузі','З’їхавши на узбіччя чи тротуар'],'Безпечна дистанція — відстань, за якої водій позаду може запобігти зіткненню без здійснення будь-якого маневру (п. 1.10).');
q('t18','terms','Що ПДР називає безпечним інтервалом?',['Відстань між боковими частинами ТЗ або між ними й іншими об’єктами, за якої гарантована безпека','Відстань до ТЗ, що їде попереду в тій самій смузі, за якої можна уникнути зіткнення','Час між увімкненням покажчика повороту і початком маневру чи перестроювання'],'Не плутай: інтервал — відстань збоку, а дистанція — до ТЗ, що їде попереду в тій самій смузі (п. 1.10).');
q('t19','terms','Яку швидкість ПДР називає безпечною?',['Ту, за якої можна безпечно керувати ТЗ і контролювати його рух у конкретних умовах','Будь-яку, що не перевищує обмеження, встановленого знаком чи ПДР','Швидкість, на 10 км/год нижчу за максимально дозволену на ділянці'],'Безпечна швидкість залежить від конкретних умов, тож у тумані чи на льоду вона може бути значно нижчою за дозволену (п. 1.10).');
q('t20','terms','Тягач везе причіп, підібраний за інструкцією, зі страховим з’єднанням і єдиною сигналізацією. Чи це буксирування?',['Ні, це експлуатація транспортного состава','Так, це буксирування на жорсткому зчепленні','Так, якщо в причепі немає людей'],'Буксирування — переміщення одним ТЗ іншого, яке не належить до експлуатації автопоїздів: на жорсткому чи гнучкому зчепленні або частковим навантаженням (п. 1.10).');
q('t21','terms','Яка зупинка за ПДР вважається вимушеною?',['Через технічну несправність ТЗ чи небезпеку, спричинену вантажем','Щоб висадити пасажира біля магазину чи забрати посилку','Щоб відповісти на телефонний дзвінок або переглянути карту'],'Вимушена зупинка — через технічну несправність, небезпеку від вантажу, стан учасника руху або появу перешкоди (п. 1.10).');
q('t22','terms','Від якого моменту відраховують гальмовий шлях?',['Від початку натискання на педаль (рукоятку) гальма','Від моменту, коли водій помітив небезпеку','Від моменту, коли колеса почали ковзати'],'Гальмовий шлях — відстань під час екстреного гальмування від початку впливу на механізм керування гальмовою системою до зупинки. Час реакції сюди не входить (п. 1.10).');
q('t23','terms','Асфальтова дорога перетинається з ґрунтовою, знаків пріоритету немає. Яка з них головна?',['Асфальтова','Ґрунтова','Вони рівнозначні'],'Дорога з покриттям є головною відносно ґрунтової навіть без знаків пріоритету (п. 1.10).');
q('t24','terms','Що ПДР називають острівцем безпеки?',['Виділений над проїзною частиною елемент на пішохідному переході, де пішоходи можуть зупинитися','Розширення тротуару біля зупинки маршрутних ТЗ, де чекають пасажири','Ділянку проїзної частини, позначену розміткою, для розвороту ТЗ'],'Острівець безпеки — конструктивно виділений над проїзною частиною засіб на наземному переході для зупинки пішоходів. До нього належить і частина розділювальної смуги, через яку пролягає перехід (п. 1.10).');
q('t25','terms','Що означає вимога «дати дорогу»?',['Не рушати, не їхати далі й не маневрувати, якщо це може змусити учасника з перевагою змінити напрямок чи швидкість','Завжди повністю зупинитися перед перехрестям, навіть якщо інших учасників руху поблизу немає','Знизити швидкість до 20 км/год і попередити інших учасників звуковим сигналом про свій намір'],'Зупинка потрібна лише тоді, коли інакше учасник з перевагою муситиме змінити напрямок руху чи швидкість (п. 1.10).');
q('t26','terms','Що таке денні ходові вогні?',['Білі світлові прилади спереду ТЗ, що покращують його видимість у світлий час доби','Жовті вогні спереду, що замінюють ближнє світло в темряві','Габаритні вогні спереду і ззаду, ввімкнені вдень'],'ДХВ — зовнішні світлові прилади білого кольору, передбачені конструкцією і встановлені спереду. Вони призначені саме для світлого часу доби (п. 1.10).');
q('t27','terms','Яку подію ПДР називає дорожньо-транспортною пригодою?',['Подію під час руху ТЗ, через яку загинули чи поранені люди або завдано матеріальних збитків','Лише зіткнення двох і більше ТЗ, у якому є загиблі чи поранені люди','Будь-яке порушення ПДР, яке зафіксувала поліція чи камера автофіксації'],'Для ДТП достатньо й самих матеріальних збитків — наприклад, пом’ятого бампера. Потерпілих може й не бути (п. 1.10).');
q('t28','terms','Що входить у поняття «дорожня обстановка», але не в «дорожні умови»?',['Наявність перешкод та інтенсивність руху','Стан поверхні проїзної частини','Похили на спусках і підйомах'],'Дорожні умови — видимість, стан і ширина проїзної частини, похили, заокруглення тощо. Обстановка — це умови плюс перешкоди, інтенсивність і рівень організації руху (п. 1.10).');
q('t29','terms','Чим шляхопровід відрізняється від естакади?',['Шляхопровід дає змогу з’їхати на іншу дорогу, естакада — ні','Естакада дає змогу з’їхати на іншу дорогу, шляхопровід — ні','Шляхопровід — лише над залізницею, естакада — лише над річкою'],'Обидві споруди можуть піднімати одну дорогу над іншою, але естакада не має з’їздів на іншу дорогу, а шляхопровід дає можливість з’їзду (п. 1.10).');
q('t30','terms','Ти в’їжджаєш у двір багатоповерхівки, знака «Житлова зона» немає. Це житлова зона?',['Так, дворові території — це житлова зона','Ні, житлова зона лише там, де є знак 5.34','Лише якщо у дворі є дитячий майданчик'],'Житлова зона — це дворові території, а також частини населених пунктів, позначені знаком 5.34 (п. 1.10).');
q('t31','terms','Що ПДР вважає залишенням місця ДТП?',['Дії учасника, спрямовані на приховання пригоди чи її обставин, через які поліції довелося розшукувати його чи ТЗ','Будь-який від’їзд з місця пригоди, навіть щоб відвезти потерпілого до лікарні','Вихід водія з авто до приїзду поліції'],'Ключове — намір приховати факт пригоди чи обставини її скоєння, через що поліція мусить розшукувати учасника або ТЗ (п. 1.10).');
q('t32','terms','Скільки ТЗ щонайменше утворюють колону за ПДР?',['Три','Два','П’ять'],'Колона — організована група з трьох і більше ТЗ, що їдуть разом в одному напрямку один за одним з постійно ввімкненим ближнім світлом (п. 1.10).');
q('t33','terms','Коли ТЗ займає крайнє праве положення на проїзній частині?',['Коли між ним і краєм не може проїхати попутний ТЗ, навіть двоколісний','Коли до краю проїзної частини не більше 1 м','Коли він у правій смузі, хоч би якою була відстань до краю'],'Крайнє положення — така відстань від краю (середини чи розділювальної смуги), що ближче до нього не може рухатися жоден попутний ТЗ, навіть двоколісний (п. 1.10).');
q('t34','terms','Що з цього ПДР вважає маневром?',['Початок руху з місця стоянки','Плавне гальмування у своїй смузі','Рух прямо через перехрестя без зміни смуги'],'Маневр — початок руху, перестроювання, поворот праворуч чи ліворуч, розворот, з’їзд з проїзної частини, рух заднім ходом (п. 1.10).');
q('t35','terms','Автобус везе туристів на екскурсію без встановленого маршруту і зупинок. Чи це маршрутний ТЗ?',['Ні, маршрутні ТЗ їдуть встановленими маршрутами з визначеними місцями посадки','Так, будь-який автобус із пасажирами вважається маршрутним ТЗ','Так, якщо в ньому більше 17 місць для сидіння з місцем водія'],'Маршрутні ТЗ — автобуси, мікроавтобуси, тролейбуси, трамваї й таксі, що рухаються встановленими маршрутами з визначеними місцями посадки (висадки) (п. 1.10).');
q('t36','terms','З електродвигуном якої потужності ТЗ вважається механічним?',['Понад 3 кВт','Понад 1 кВт','Понад 10 кВт'],'Механічний ТЗ рухається з допомогою двигуна. Термін охоплює й трактори, самохідні машини, тролейбуси та ТЗ з електродвигуном понад 3 кВт (п. 1.10).');
q('t37','terms','Де межі мосту за ПДР?',['Початок і кінець пролітних споруд','Знаки з назвою річки чи яру','Місця, де починаються й закінчуються перила'],'Міст — споруда для руху через річку, яр та інші перешкоди. Його межі — початок і кінець пролітних споруд (п. 1.10).');
q('t38','terms','Триколісний механічний ТЗ має дозволену максимальну масу 350 кг. До чого він прирівнюється?',['До мотоциклів','До легкових автомобілів','До мопедів'],'До мотоциклів прирівнюються моторолери, мотоколяски, триколісні та інші механічні ТЗ з дозволеною максимальною масою не більше 400 кг (п. 1.10).');
q('t39','terms','Що для ПДР визначає межі населеного пункту?',['Дорожні знаки на в’їзді й виїзді','Перші й останні будинки вздовж дороги','Межа території громади на карті'],'Населений пункт — забудована територія, в’їзди на яку й виїзди з якої позначають знаками 5.49–5.52 (п. 1.10).');
q('t40','terms','У межах твоєї смуги назустріч загальному потоку їде інше авто. Як це називають ПДР?',['Небезпека для руху','Перешкода для руху','Обмежена оглядовість'],'Рух іншого ТЗ у межах твоєї смуги назустріч загальному потоку — окремий випадок небезпеки для руху. Перешкодою його не вважають (п. 1.10).');
q('t41','terms','Огляд дороги попереду закриває вантажівка, що стоїть на узбіччі. Як це називається в ПДР?',['Обмежена оглядовість','Недостатня видимість','Засліплення'],'Оглядовість обмежують геометрія дороги, споруди, насадження, інші об’єкти й ТЗ. Недостатня видимість — через сутінки, туман, дощ, снігопад тощо (п. 1.10).');
q('t42','terms','Автобус везе організовану групу з 32 дітей. Хто, крім водія, має бути з ними в поїздці?',['Керівник і медичний працівник','Лише керівник','Лише медичний працівник'],'Організована група — від 10 дітей з керівником. На групу з 30 і більше дітей додатково призначають медичного працівника (п. 1.10).');
q('t43','terms','На перехресті немає розмітки, знаків і пішохідних світлофорів. Як визначити межі пішохідного переходу?',['Шириною тротуарів чи узбіч','Переходу там немає взагалі','Смугою завширшки 4 м від краю перехрестя'],'На перехресті без пішохідних світлофорів, знаків і розмітки межі переходу визначає ширина тротуарів чи узбіч (п. 1.10).');
q('t44','terms','Світлофор на пішохідному переході блимає жовтим. Який це перехід за ПДР?',['Нерегульований','Регульований','Тимчасово закритий для пішоходів'],'Нерегульований перехід — без регулювальника, а світлофори відсутні, вимкнені або працюють у режимі миготливого жовтого (п. 1.10).');
q('t45','terms','Тролейбус за ПДР — рейковий чи нерейковий ТЗ?',['Нерейковий','Рейковий','Рейковий, як і трамвай, бо живиться від контактної мережі'],'Рейкові ТЗ — лише трамвай і платформи зі спецобладнанням, що рухаються трамвайними коліями. Усі інші, зокрема тролейбус, — нерейкові (п. 1.10).');
q('t46','terms','Хто, крім поліцейського, прирівнюється до регулювальника, якщо має посвідчення, пов’язку, жезл і формений одяг?',['Черговий на залізничному переїзді','Охоронець стоянки торговельного центру','Будь-який водій, що зупинився після ДТП'],'Також прирівнюються працівники військової інспекції безпеки дорожнього руху, дорожньо-експлуатаційної служби й черговий на поромній переправі (п. 1.10).');
q('t47','terms','Ти виїжджаєш за кордон на своєму авто. Що ПДР вимагають щодо номерного знака?',['Його літери відповідають латинському алфавіту, а на авто є розпізнавальний знак держави','Літери можуть бути будь-якими, розпізнавальний знак держави не потрібен','Підійде будь-який, якщо є нотаріальний переклад техпаспорта'],'Також потрібні реєстраційні документи на ТЗ і посвідчення водія, що відповідають Конвенції про дорожній рух (Відень, 1968) (п. 29.1).');
q('t48','terms','За загальним правилом, коли іноземне авто в міжнародному русі треба тимчасово зареєструвати в Україні?',['Якщо воно тут більше двох місяців','Якщо воно тут більше шести місяців','Одразу після перетину кордону'],'Виняток — авто іноземців та осіб без громадянства, які в Україні на відпочинку чи лікуванні за путівками на визначений Держмитслужбою термін (п. 29.2).');
q('t49','terms','Умови й порядок руху якої колони треба узгоджувати з поліцією?',['Колони з більш як п’яти механічних ТЗ','Будь-якої колони від трьох ТЗ','Лише колони з понад десяти вантажівок'],'З підрозділами Нацполіції узгоджують рух колон з більш як п’яти механічних ТЗ, а також порядок буксирування двох і більше ТЗ (п. 32.1 «б», «в»).');
q('t50','terms','Чи можна на СТО перенести чи відновити ідентифікаційний номер кузова без жодних погоджень?',['Ні, спершу це узгоджують із сервісним органом МВС','Так, якщо СТО спеціалізується на ремонті кузовів','Так, якщо старий номер пошкодила корозія'],'Змінювати, знищувати, переносити чи відновлювати ідентифікаційні номери кузова, шасі (рами) чи двигуна без узгодження з сервісними органами МВС заборонено навіть на спецпідприємствах (п. 32.3).');

/* Обов’язки водія */
q('d1','duties','Які документи водій має мати при собі (паперові або в Дії)?',['Посвідчення водія, реєстраційний документ на авто і поліс автоцивілки','Лише посвідчення водія','Посвідчення водія і паспорт'],'Усі три документи можна показати й в електронному вигляді.');
q('d2','duties','З якого вмісту алкоголю в крові водій вважається у стані сп’яніння?',['Понад 0,2 проміле','Понад 0,5 проміле','Понад 0,8 проміле'],'Поріг — 0,2 ‰. Навіть невелика доза сповільнює реакцію, тож найбезпечніше — нуль.');
q('d3','duties','Чи можна під час руху говорити по телефону, тримаючи його в руці?',['Ні, лише через гарнітуру або гучний зв’язок','Так, якщо швидкість до 20 км/год','Так, у межах населеного пункту'],'ПДР забороняє користуватися засобами зв’язку, тримаючи їх у руці під час руху.');
q('d4','duties','Ти учасник ДТП, є потерпілі. Що робиш першочергово?',['Зупиняєшся, вмикаєш аварійку, ставиш знак аварійної зупинки, допомагаєш потерпілим і викликаєш швидку та поліцію','Відганяєш авто на узбіччя, щоб не було затору','Їдеш по допомогу і повертаєшся пізніше'],'Переміщувати авто й предмети, що стосуються пригоди, та залишати місце ДТП не можна.');
q('d5','duties','Чи має пристібатися пасажир на задньому сидінні?',['Так, якщо авто обладнане ременями безпеки','Ні, ремінь потрібен лише спереду','Лише поза населеними пунктами'],'Водій не має права перевозити пасажирів, не пристебнутих ременями, — ні спереду, ні ззаду.');
q('d6','duties','Як перевозити в легковику дитину зростом до 145 см або молодшу за 12 років?',['У спеціальному засобі — автокріслі чи бустері, пристебнутою ременем','На руках у дорослого на задньому сидінні','На задньому сидінні, просто пристебнутою'],'Без спеціальних утримувальних засобів таких дітей перевозити заборонено.');
q('d7','duties','У дорозі сильно хилить на сон. Як правильно?',['Зупинитися в дозволеному місці й відпочити','Відкрити вікно й прискоритися, щоб швидше доїхати','Ввімкнути гучну музику й їхати далі'],'Керувати у стані втоми, що впливає на реакцію, ПДР забороняє.');
q('d8','duties','Чи можна дати покермувати другові без посвідчення водія?',['Ні, хіба що це навчальна їзда з інструктором','Так, якщо ти сидиш поруч','Так, на порожній дорозі'],'Передавати керування особі без посвідчення відповідної категорії заборонено, крім навчальної їзди.');
q('d9','duties','Із твого авто на дорогу висипався вантаж, і прибрати його одразу неможливо. Що ти зобов’язана зробити?',['Попередити інших учасників руху й повідомити поліцію або власника дороги','Поїхати далі, бо прибирання доріг — не обов’язок водія','Лише ввімкнути аварійку і чекати, поки хтось прибере'],'Хто створив перешкоду, має її усунути, а якщо не може — попередити інших і повідомити поліцію, власника дороги або уповноважений ним орган (п. 1.5).');
q('d10','duties','Яким документом, крім поліса автоцивілки українського страховика, ПДР дозволяють підтвердити страхування?',['Сертифікатом «Зелена картка», виданим іноземним страховиком','Полісом добровільного страхування КАСКО','Протоколом обов’язкового технічного контролю'],'Водій має мати чинний поліс ОСЦПВ (паперовий чи електронний) або «Зелену картку» іноземного страховика (п. 2.1 «ґ»).');
q('d11','duties','На твоєму авто знак «Водій з інвалідністю», але явних ознак інвалідності немає. Що треба мати при собі?',['Документ, що підтверджує інвалідність водія або пасажира','Нічого, достатньо самого розпізнавального знака','Окремий дозвіл поліції на використання знака'],'Без документа, що підтверджує інвалідність, користуватися цим знаком заборонено, крім випадків з явними ознаками інвалідності (п. 2.1 «д», 2.9 «е»).');
q('d12','duties','Ти ставиш авто на місце, відведене для водіїв, які перевозять дітей до трьох років. Що для цього потрібно?',['Розпізнавальний знак і документ про вік дитини','Лише дитяче крісло, встановлене в салоні','Нічого, якщо дитина зараз їде з тобою'],'Без знака «Водій, який перевозить дітей віком до трьох років» і документа (паперового чи електронного) про вік дитини зупинятися там заборонено (п. 2.1 «е», 2.9 «є»).');
q('d13','duties','Власниця передає авто у користування подрузі. Що для цього потрібно за ПДР?',['Посвідчення потрібної категорії в подруги й реєстраційний документ на авто','Лише нотаріальна довіреність, посвідчення водія не обов’язкове','Достатньо усного дозволу власниці, документи не передаються'],'Власник може передати ТЗ у користування особі з посвідченням відповідної категорії, передавши їй реєстраційний документ на цей ТЗ (п. 2.2).');
q('d14','duties','Що водій зобов’язаний зробити перед виїздом?',['Перевірити технічний стан і комплектність авто та кріплення вантажу','Прогріти двигун щонайменше 10 хвилин на холостому ходу','Лише переконатися, що в баку вистачить пального'],'Перед виїздом треба перевірити і забезпечити справний стан і комплектність ТЗ, правильність розміщення та кріплення вантажу (п. 2.3 «а»).');
q('d15','duties','Ти — інструкторка з водіння, за кермом учень, ви їдете містом. Чи можна тобі не пристібатися?',['Ні, для інструктора ПДР винятку не передбачають','Так, інструктор може не пристібатися завжди','Так, але лише в межах населеного пункту'],'Інструктор теж вважається водієм (п. 1.10). Не пристібатися дозволено лише в населених пунктах людям з інвалідністю за фізіологічних протипоказань і в оперативних та спеціальних ТЗ (п. 2.3 «в»).');
q('d16','duties','Кому ПДР дозволяють не пристібатися в населеному пункті?',['Людям з інвалідністю, яким фізіологічно неможливо пристебнутися','Водіям таксі, які перевозять пасажирів за викликом','Пасажирам на задньому сидінні, якщо швидкість невелика'],'Такий виняток мають також водії й пасажири оперативних і спеціальних ТЗ. Для таксі окремого винятку немає (п. 2.3 «в»).');
q('d17','duties','Ти їдеш на мопеді з пасажиром. Що вимагають ПДР щодо шоломів?',['Обоє мають бути в застебнутих мотошоломах','Шолом обов’язковий лише для водія','Шолом потрібен лише поза населеними пунктами'],'На мотоциклі й мопеді водій має бути в застебнутому мотошоломі й не перевозити пасажирів без нього (п. 2.3 «г», 5.2 «б»).');
q('d18','duties','Ти виявила на дорозі перешкоду, яку хтось залишив і яка заважає руху. Що ПДР зобов’язують зробити?',['Повідомити дорожньо-експлуатаційну організацію або поліцію','Нічого, це справа лише дорожніх служб','Перекрити дорогу своїм авто до приїзду служб'],'Водій зобов’язаний повідомляти дорожньо-експлуатаційні організації або поліцію про виявлені факти створення перешкод для руху (п. 2.3 «е»).');
q('d19','duties','Чи можна викинути сміття з вікна авто на узбіччя?',['Ні, забруднювати дорогу і смугу відведення заборонено','Так, якщо це лише недопалок чи огризок','Так, поза населеними пунктами це дозволено'],'І водії, і пасажири зобов’язані не забруднювати проїзну частину та смугу відведення автомобільних доріг (п. 2.3 «ґ», 5.2 «в»).');
q('d20','duties','Поліцейський зупинив тебе. Що, крім документів, ти зобов’язана дати йому перевірити?',['Номери агрегатів і комплектність ТЗ','Вміст свого телефона й сумки','Нічого, крім документів'],'На вимогу поліцейського водій пред’являє документи з п. 2.1 і дає змогу перевірити номери агрегатів і комплектність ТЗ, а за законних підстав — оглянути його (п. 2.4).');
q('d21','duties','Ти їдеш у прикордонній смузі, і прикордонник вимагає зупинитися. Що ти маєш зробити за ПДР?',['Пред’явити реєстраційний документ на ТЗ і дати оглянути авто','Лише показати поліс автоцивілки, огляд не дозволений','Нічого — перевіряти водіїв може лише поліцейський'],'У прикордонній смузі на вимогу уповноваженої особи Держприкордонслужби водій пред’являє реєстраційний документ, дає оглянути ТЗ і перевірити номери агрегатів (п. 2.4-3).');
q('d22','duties','Поліцейський вимагає пройти огляд на стан сп’яніння. Як за ПДР?',['Пройти медичний огляд у встановленому порядку','Можна відмовитися, якщо почуваєшся тверезою','Пройти лише за письмовою згодою власника авто'],'Водій зобов’язаний на вимогу поліцейського пройти огляд на стан алкогольного, наркотичного чи іншого сп’яніння або впливу ліків (п. 2.5).');
q('d23','duties','З якою метою поліцейський за наявності підстав може направити водія на позачерговий медогляд?',['Щоб визначити, чи здатен водій безпечно керувати ТЗ','Щоб замінити водієві посвідчення на нове','Щоб перевірити, як водій знає ПДР і знаки'],'Позачерговий медичний огляд проводять, щоб визначити здатність водія безпечно керувати транспортним засобом (п. 2.6).');
q('d24','duties','Медик просить твоє авто, щоб доставити до лікарні людину, якій потрібна екстрена допомога. Як за ПДР?',['Надати авто для доставки до найближчого закладу охорони здоров’я','Відмовити, бо надавати авто треба лише поліцейським','Надати лише після підписання договору оренди'],'Водій зобов’язаний надати ТЗ поліцейським і медикам для доставки осіб, які потребують екстреної допомоги (п. 2.7 «а»). Власник має право на відшкодування витрат (п. 2.12 «б»).');
q('d25','duties','Хто з водіїв не зобов’язаний надавати свій ТЗ поліцейським чи медикам для невідкладних потреб?',['Водій авто дипломатичного представництва','Водій таксі під час роботи','Водій зі стажем до 2 років'],'Виняток — ТЗ дипломатичних та інших представництв іноземних держав, міжнародних організацій, а також оперативні й спеціальні ТЗ (п. 2.7).');
q('d26','duties','Авто пошкоджено через вибоїну, стан якої не відповідав вимогам безпеки руху. Яке право має власник?',['На відшкодування завданих збитків','Лише на позачерговий техогляд за рахунок держави','Права на відшкодування немає, винен лише водій'],'Власник ТЗ має право на відшкодування збитків через невідповідність стану доріг, вулиць і залізничних переїздів вимогам безпеки руху (п. 2.12 «в»).');
q('d27','duties','Від вимог якого знака може відступати водій з інвалідністю на авто з розпізнавальним знаком «Водій з інвалідністю»?',['3.35 «Стоянку заборонено»','3.21 «В’їзд заборонено»','2.2 «Проїзд без зупинки заборонено»'],'Можна відступати від знаків 3.1, 3.2, 3.35–3.38, а від 3.34 — лише якщо під ним табличка 7.18 «Крім осіб з інвалідністю» (п. 2.8).');
q('d28','duties','Ти прийняла ліки, що знижують увагу і швидкість реакції. Чи можна сідати за кермо?',['Ні, керувати під впливом таких препаратів заборонено','Так, якщо їхати повільно й обережно','Так, якщо ці ліки призначив тобі лікар'],'ПДР забороняють керувати під впливом лікарських препаратів, що знижують увагу та швидкість реакції, навіть призначених лікарем (п. 2.9 «а», «б»).');
q('d29','duties','У тебе висока температура і сильна слабкість. Чи можна керувати авто?',['Ні, керувати у хворобливому стані заборонено','Так, якщо поїздка зовсім коротка','Так, але лише в межах населеного пункту'],'ПДР забороняють керувати у хворобливому стані, у стані стомлення чи під впливом ліків, що знижують реакцію й увагу (п. 2.9 «б»).');
q('d30','duties','З якої відстані мають чітко читатися символи номерного знака, щоб він не вважався закритим чи забрудненим?',['20 м','10 м','50 м'],'Заборонено їхати з номером, символи якого не видно чітко з 20 м, а також неосвітленим у темряві чи перевернутим (п. 2.9 «в»).');
q('d31','duties','Друг має посвідчення водія, але він помітно напідпитку. Чи можна передати йому кермо?',['Ні, передавати керування особі в стані сп’яніння заборонено','Так, якщо він каже, що почувається нормально','Так, якщо ти сидиш поруч і контролюєш його дії'],'Не можна передавати керування особам у стані сп’яніння, під впливом ліків, що знижують увагу, або у хворобливому стані (п. 2.9 «г»).');
q('d32','duties','Подруга має права, але посвідчення немає при собі ні в паперовому, ні в електронному вигляді. Чи можна передати їй кермо?',['Ні, посвідчення має бути в неї при собі','Так, якщо вона назве номер посвідчення','Так, якщо ти власниця авто й сидиш поруч'],'Передавати керування можна лише особі, яка має при собі посвідчення відповідної категорії, крім навчальної їзди (п. 2.2, 2.9 «ґ»).');
q('d33','duties','Кому ПДР дозволяють під час руху говорити по телефону, тримаючи його в руці?',['Водіям оперативних ТЗ під час невідкладного службового завдання','Водіям таксі під час прийому замовлень від диспетчера','Будь-якому водію, якщо швидкість не перевищує 20 км/год'],'Іншим водіям користуватися засобами зв’язку, тримаючи їх у руці, під час руху заборонено (п. 2.9 «д»).');
q('d34','duties','Після ДТП ти мусиш сама відвезти потерпілого до лікарні. Що треба зробити перед від’їздом?',['Зафіксувати розташування слідів пригоди і положення свого авто','Прибрати уламки й відсунути своє авто на узбіччя','Нічого, головне — якнайшвидше доїхати до лікарні'],'Перед від’їздом треба зафіксувати сліди пригоди й положення авто після зупинки, а в лікарні — назвати прізвище й номерний знак, показати документи і повернутися на місце (п. 2.10 «ґ»).');
q('d35','duties','Ти учасниця ДТП. Що ПДР зобов’язують зробити щодо свідків пригоди?',['Записати прізвища та адреси очевидців','Попросити їх піти, щоб не заважали','Нічого, свідками займається лише поліція'],'Водій повідомляє про ДТП поліцію, записує прізвища та адреси очевидців і чекає прибуття поліцейських (п. 2.10 «д»).');
q('d36','duties','Що заборонено водію — учаснику ДТП до проведення медогляду?',['Вживати алкоголь чи наркотики без призначення медика','Телефонувати рідним, знайомим чи страховику','Виходити з авто, поки не приїде поліція'],'До медогляду не можна вживати алкоголь, наркотики та ліки на їх основі без призначення медика, крім препаратів з офіційного складу аптечки (п. 2.10 «є»).');
q('d37','duties','ДТП без потерпілих і шкоди третім особам, авто можуть безпечно рухатися, водії згодні щодо обставин. Що ПДР дозволяють?',['Скласти й підписати схему та поїхати до найближчого поста чи органу поліції','Просто роз’їхатися, нічого не оформлюючи і нікуди не звертаючись','Лише чекати поліцію на місці — інших варіантів немає'],'За цих умов водії можуть, склавши схему пригоди й підписавши її, самі прибути до поста або органу поліції для оформлення (п. 2.11).');
q('d38','duties','Коли водії можуть оформити ДТП без поліції, склавши спільне повідомлення для страховика?',['Зіткнулися два застраховані авто, шкода лише їм, без постраждалих, водії тверезі й згодні','Будь-яке ДТП з незначною шкодою, навіть за участю трьох і більше авто','Є легко травмований пішохід, але він не має претензій до винуватця'],'Має бути зіткнення лише двох застрахованих ТЗ без шкоди людям та іншому майну. Склавши таке повідомлення, водії можуть залишити місце ДТП і не повідомляти поліцію (п. 2.11).');
q('d39','duties','З якого віку можна отримати право керувати легковим автомобілем (категорія B)?',['З 18 років','З 17 років','З 16 років'],'Категорії B1, B, C1, C — з 18 років, мотоцикли (A1, A) — з 16, автобуси — з 21 (п. 2.13).');
q('d40','duties','Скільки сидячих місць, крім місця водія, може мати автомобіль категорії B?',['Не більше восьми','Не більше дев’яти','Не більше шести'],'Категорія B — автомобілі з дозволеною максимальною масою до 3500 кг і не більше ніж вісьмома сидячими місцями, крім водійського (п. 2.13).');
q('d41','duties','Легковик тягне причіп повною масою понад 750 кг. Посвідчення якої категорії потрібне?',['BE','B','C1'],'З причепом до 750 кг вистачає категорії B. Для важчого причепа потрібна BE, право на яку надають з 19 років (п. 2.13).');
q('d42','duties','З якого віку можна отримати право керувати мотоциклом чи мопедом (категорії A1, A)?',['З 16 років','З 14 років','З 18 років'],'Мототранспортом (A1, A) — з 16 років. З 14 років можна лише навчатися водінню мотоцикла чи мопеда (п. 2.13, 24.2).');
q('d43','duties','Поліцейський зупинив тебе для перевірки. Що ти маєш право знати?',['Причину зупинки, його прізвище і посаду','Лише номер його службового авто','Нічого, поки не пред’явиш документи'],'Водій має право знати причину зупинки, перевірки й огляду, прізвище і посаду посадової особи, а також вимагати показати посвідчення (п. 2.14 «в», «г»).');
q('d44','duties','Коли водій має право відступати від вимог законодавства?',['За непереборної сили або щоб запобігти загибелі чи каліцтву людей','Коли водій поспішає і запізнюється на важливу зустріч','Коли вночі на дорозі немає інших учасників руху'],'Відступати від вимог можна лише за дії непереборної сили або коли іншими засобами неможливо запобігти власній загибелі чи каліцтву громадян (п. 2.14 «е»).');
q('d45','duties','Ти водійка таксі. Чи можна рухатися смугою для маршрутних ТЗ, позначеною знаком 5.11?',['Так, і висаджувати там пасажирів з урахуванням правил зупинки','Ні, вона лише для автобусів і тролейбусів','Лише вночі, коли маршрутний транспорт не ходить'],'Водій таксі може рухатися смугою для маршрутних ТЗ (знаки 5.8, 5.11) і здійснювати в її межах посадку й висадку пасажирів (п. 2.15).');
q('d46','duties','Хто з цих водіїв НЕ має права рухатися смугою для маршрутних ТЗ?',['Водій мотоцикла з боковим причепом','Водій мотоцикла без бокового причепа','Водій мопеда'],'Смугою для маршрутних ТЗ можуть рухатися мотоцикли й мопеди, але не мотоцикли з боковим причепом, мотоколяски і триколісні ТЗ (п. 2.16).');
q('d47','duties','Звідки пасажиру можна виходити з авто, якщо немає посадкового майданчика, тротуару чи узбіччя?',['З крайньої смуги, але не з боку суміжної смуги руху','З будь-якого боку, якщо авто вже зупинилося','Лише з боку суміжної смуги, де більше місця'],'Посадка й висадка — лише після зупинки: з майданчика, тротуару чи узбіччя, а якщо це неможливо — з крайньої смуги, безпечно й не з боку сусідньої смуги (п. 5.1).');
q('d48','duties','Що забороняється пасажирам щодо дверей авто?',['Відчиняти, поки авто не зупинилося біля тротуару, краю дороги чи узбіччя','Зачиняти двері самостійно, без допомоги чи дозволу водія','Відчиняти двері на стоянці, коли двигун вимкнений'],'А ще пасажирам заборонено перешкоджати зачиненню дверей і їздити на підніжках чи виступах ТЗ (п. 5.3 «б», «в»).');
q('d49','duties','Ти пасажирка авто, що потрапило в ДТП. Що ПДР зобов’язують тебе зробити?',['Допомогти потерпілим, повідомити поліцію й дочекатися її на місці','Нічого, бо за ДТП і його наслідки відповідає лише водій','Одразу піти, щоб не заважати водіям оформлювати ДТП'],'Пасажир причетного до ДТП ТЗ має надати можливу допомогу потерпілим, повідомити поліцію і перебувати на місці до її прибуття (п. 5.4).');
q('d50','duties','Кого дозволено навчати водінню?',['Лише осіб без медичних протипоказань, що підтверджено медичною довідкою','Будь-кого з 16 років, медична довідка не потрібна','Лише тих, хто вже має посвідчення іншої категорії'],'Навчати водінню можна лише осіб без медичних протипоказань, що підтверджує дійсна медична довідка встановленого зразка (п. 24.1).');
q('d51','duties','Скільки щонайменше має бути років людині, яка навчається водінню автомобіля?',['16 років','18 років','14 років'],'Для автомобіля — не менше 16 років, для мотоцикла чи мопеда — 14. Учень має мати при собі документ про вік (п. 24.2).');
q('d52','duties','Де має проходити початкове навчання водінню?',['На закритому майданчику, автодромі або там, де немає інших учасників руху','Одразу на жвавих вулицях міста, щоб швидше набратися досвіду','На автомагістралі в нічний час, коли там мало інших авто'],'Початкове навчання — лише на закритих майданчиках, автодромах або в місцях, де відсутні інші учасники руху (п. 24.4).');
q('d53','duties','За якої умови дозволена навчальна їзда дорогами?',['У присутності спеціаліста з підготовки водіїв і за достатніх початкових навичок учня','Якщо поруч сидить будь-який водій зі стажем понад 3 роки','Будь-коли, якщо на авто є знак «Навчальний транспортний засіб»'],'Навчальна їзда на дорогах — тільки зі спеціалістом з підготовки водіїв і коли учень уже має достатні початкові навички (п. 24.5).');
q('d54','duties','Чим, крім знака «Навчальний транспортний засіб», обладнують навчальний легковик?',['Додатковою педаллю гальма (і зчеплення, якщо є) та дзеркалом для спеціаліста','Додатковим кермом і окремим замком запалювання для інструктора','Окремим звуковим сигналом для попередження інших'],'Навчальні ТЗ (крім автобусів) мають додаткові педалі гальма, зчеплення (за наявності) і, якщо можливо, акселератора, а також дзеркало для спеціаліста (п. 24.8).');
q('d55','duties','Де заборонено навчання водінню?',['У житловій зоні, на дорогах для автомобілів і автомагістралях','На будь-яких дорогах у населених пунктах','На дорогах із трамвайними коліями та велосмугами'],'Навчати водінню заборонено в житловій зоні, на дорогах для автомобілів (знак 5.3) та автомагістралях (п. 24.9).');

/* Світлофор і регулювальник */
q('g1','signals','Що означає жовтий сигнал світлофора (не миготливий)?',['Забороняє рух і попереджає про зміну сигналів','Дозволяє рух, якщо встигаєш проїхати','Дозволяє рух з обережністю'],'Виняток: якщо зупинитися можна лише екстреним гальмуванням, дозволено проїхати далі.');
q('g2','signals','Що означає миготливий жовтий сигнал?',['Перехрестя нерегульоване: їдь, керуючись знаками пріоритету і правилами проїзду','Світлофор несправний — рух заборонено','Треба обов’язково зупинитися перед стоп-лінією'],'Миготливий жовтий попереджає про небезпеку, а черговість визначають знаки або правило перешкоди справа.');
q('g3','signals','Що означає миготливий зелений?',['Рух дозволено, але скоро ввімкнеться заборонний сигнал','Рух заборонено','Можна повертати лише праворуч'],'Це попередження: оціни, чи встигнеш, і готуйся зупинитися.');
q('g4','signals','Горить червоний і зелена стрілка праворуч у додатковій секції. Що можна?',['Повернути праворуч, давши дорогу ТЗ з інших напрямків','Повернути праворуч з перевагою над усіма','Лише стояти до основного зеленого'],'Рух за стрілкою разом із червоним чи жовтим дозволено, лише якщо ти поступаєшся ТЗ з інших напрямків.');
q('g5','signals','Регулювальник підняв руку вгору. Що це означає?',['Рух заборонено всім учасникам у всіх напрямках','Скоро зміна сигналу — проїжджай швидше','Можна повертати праворуч'],'Як і жовтий: хто не може зупинитися без екстреного гальмування, може проїхати.');
q('g6','signals','Регулювальник стоїть до тебе боком, руки опущені або витягнуті в сторони. Куди можна їхати?',['Прямо і праворуч','Лише праворуч','У будь-якому напрямку'],'З лівого і правого боку регулювальника нерейковим ТЗ можна прямо і праворуч, трамваю — лише прямо.');
q('g7','signals','Регулювальник стоїть до тебе грудьми, права рука витягнута вперед. Куди можна?',['Лише праворуч','Прямо і праворуч','Рух заборонено'],'З боку грудей — лише праворуч. З боку лівого плеча — в усіх напрямках. Зі спини й з правого боку — рух заборонено.');
q('g8','signals','Світлофор і регулювальник показують різне. Кого слухати?',['Регулювальника','Світлофор','Того, хто дозволяє рух'],'Вимоги регулювальника мають перевагу над світлофором і знаками.');
q('g9','signals','За допомогою чого, за ПДР, здійснюється регулювання дорожнього руху?',['Знаки, розмітку, дорожнє обладнання, світлофори і регулювальників','Лише світлофори, регулювальників і дорожні знаки','Знаки, розмітку і світлофори, але не регулювальників'],'Рух регулюють і знаки, і розмітка, і дорожнє обладнання, і світлофори, і регулювальники (п. 8.1).');
q('g10','signals','Постійний дорожній знак і розмітка суперечать одне одному. Чим керуватися?',['Знаком','Розміткою','Тим, що менше обмежує рух'],'Дорожні знаки мають перевагу перед дорожньою розміткою (п. 8.2).');
q('g11','signals','На щиті з жовтим фоном стоїть тимчасовий знак, який суперечить постійному. Чим керуватися?',['Тимчасовим знаком','Постійним знаком','Тим, що стоїть ближче до тебе'],'Тимчасові знаки — на переносних пристроях, дорожньому обладнанні чи на щиті з жовтим фоном — мають перевагу перед постійними (п. 8.2).');
q('g12','signals','З якої відстані за напрямком руху мають бути видимі дорожні знаки?',['Не менш як зі 100 м','Не менш як з 50 м','Не менш як з 300 м'],'Знаки мають бути видимі щонайменше зі 100 м і розміщені не вище 6 м над проїзною частиною (п. 8.2-1).');
q('g13','signals','Сигнали світлофора мають перевагу перед знаками пріоритету. Який сигнал — виняток?',['Жовтий миготливий','Червоний миготливий','Зелений миготливий'],'На жовтий миготливий перехрестя вважається нерегульованим: керуються знаками пріоритету і правилами нерегульованих перехресть. Решта сигналів мають перевагу над знаками (пп. 8.3, 16.1).');
q('g14','signals','Регулювальник жестом вимагає від тебе дії, що суперечить знакам і розмітці. Як вчинити?',['Виконати вимогу регулювальника','Діяти за знаками і розміткою','Зупинитися й чекати, доки жест і знаки збігатимуться'],'Додаткові вимоги регулювальника обов’язкові, навіть якщо суперечать сигналам світлофорів, знакам і розмітці (п. 8.3).');
q('g15','signals','Що встановлюють знаки пріоритету?',['Черговість проїзду перехресть, перехрещень проїзних частин або вузьких ділянок','Обов’язкові напрямки руху на перехрестях і перехрещеннях доріг','Найбільшу дозволену швидкість на перехрестях і вузьких ділянках'],'Знаки пріоритету визначають, хто проїжджає першим (п. 8.4 «б»). Напрямки руху задають наказові знаки.');
q('g16','signals','Як дорожня розмітка співвідноситься з дорожніми знаками, коли їх застосовують разом?',['Підкреслює або уточнює їхні вимоги','Скасовує вимоги знаків на цій ділянці','Розмітку наносять лише там, де знаків немає'],'Розмітка використовується окремо або разом зі знаками, вимоги яких вона підкреслює або уточнює (п. 8.5).');
q('g17','signals','Яких кольорів бувають сигнали світлофорів за ПДР?',['Зеленого, жовтого, червоного і біло-місячного','Зеленого, жовтого, червоного і синього','Лише зеленого, жовтого і червоного'],'Світлофори мають сигнали зеленого, жовтого, червоного і біло-місячного кольорів (п. 8.7); біло-місячні — зокрема, у трамвайних світлофорах і на залізничних переїздах (пп. 8.7.5, 8.7.6).');
q('g18','signals','Світлофор із горизонтальним розташуванням сигналів. Де розташований червоний?',['Ліворуч','Праворуч','Посередині'],'У горизонтальних світлофорах червоний ліворуч, зелений праворуч; у вертикальних — червоний зверху, зелений знизу (п. 8.7.1).');
q('g19','signals','На якому рівні розташовані додаткові секції зі стрілками у вертикальному світлофорі?',['На рівні зеленого сигналу','На рівні червоного сигналу','На рівні жовтого сигналу'],'Одна або дві додаткові секції із зеленими стрілками — на рівні зеленого (п. 8.7.2). На рівні червоного буває лише біла табличка зі стрілкою (п. 8.7).');
q('g20','signals','Основний сигнал світлофора — зелена стрілка праворуч на чорному фоні. Куди можна їхати?',['Праворуч','Прямо і праворуч','У будь-якому напрямку'],'Зелена стрілка на чорному фоні дозволяє рух лише в зазначеному напрямку (п. 8.7.3 «б»).');
q('g21','signals','Горить зелена стрілка ліворуч. Чи можна за нею розвернутися?',['Так, якщо розворот не заборонений знаками','Ні, стрілка дозволяє лише поворот ліворуч','Лише після вмикання основного зеленого'],'Стрілка, що дозволяє поворот ліворуч, дозволяє й розворот, якщо його не заборонено дорожніми знаками (п. 8.7.3 «б»).');
q('g22','signals','Горить основний зелений і разом з ним — стрілка праворуч у додатковій секції. Що вона означає для тебе?',['Повертаючи праворуч, ти маєш перевагу перед ТЗ з інших напрямків','Повертаючи праворуч, ти поступаєшся ТЗ з інших напрямків','Поворот праворуч дозволено лише маршрутним ТЗ'],'Додаткова стрілка, увімкнена разом із зеленим, дає перевагу в її напрямку перед ТЗ з інших напрямків (п. 8.7.3 «б»).');
q('g23','signals','Що за ПДР показує цифрове табло біля світлофора?',['Скільки секунд лишилося до кінця зеленого сигналу','Рекомендовану швидкість проїзду перехрестя','Скільки секунд триватиме жовтий сигнал'],'Цифрові табло інформують водіїв про час (у секундах), що залишився до кінця горіння зеленого сигналу (п. 8.7.3 «в»).');
q('g24','signals','На основний зелений сигнал нанесена чорна контурна стрілка. Що вона означає?',['Є додаткова секція, а контурна стрілка показує інші дозволені напрямки','Рух у напрямку контурної стрілки заборонено','У напрямку стрілки ти маєш перевагу перед усіма'],'Чорна контурна стрілка на зеленому інформує про наявність додаткової секції і вказує інші дозволені напрямки, ніж сигнал додаткової секції (п. 8.7.3 «г»).');
q('g25','signals','Над пішохідним переходом миготять два жовтих сигнали. Що це означає?',['Рух дозволено, але це небезпечний нерегульований перехід','Рух заборонено, доки сигнали не перестануть миготіти','Перехід закрито, пішоходів на ньому не буде'],'Жовтий миготливий або два жовтих миготливих сигнали дозволяють рух і попереджають про небезпечне нерегульоване перехрестя чи пішохідний перехід (п. 8.7.3 «д»).');
q('g26','signals','Чи можна рушити на червоний миготливий сигнал, якщо переконалася, що нікого немає?',['Ні, червоний миготливий теж забороняє рух','Так, після повної зупинки','Так, якщо поруч немає пішоходів'],'Червоний сигнал, у тому числі миготливий, а також два червоних миготливих забороняють рух (п. 8.7.3 «е»).');
q('g27','signals','Горить червоний, а на його рівні — біла табличка із зеленою стрілкою праворуч. Як можна повернути?',['З крайньої правої смуги, пропустивши всіх, хто рухається на дозвільний сигнал','З будь-якої смуги, пропустивши лише пішоходів','З крайньої правої смуги, маючи перевагу над іншими'],'Стрілка на табличці дозволяє рух на червоний з крайньої правої смуги, якщо дати дорогу ТЗ і пішоходам, що рухаються з інших напрямків на дозвільний сигнал (пп. 8.7.3 «е», 16.9).');
q('g28','signals','Дорога з одностороннім рухом, горить червоний і табличка із зеленою стрілкою ліворуч. З якої смуги можна повернути?',['З крайньої лівої','З крайньої правої','З будь-якої'],'На дорогах з одностороннім рухом за стрілкою на табличці ліворуч рухаються з крайньої лівої смуги, надаючи перевагу іншим (п. 8.7.3 «е»).');
q('g29','signals','Одночасно горять червоний і жовтий. Що це означає?',['Рух заборонено, незабаром увімкнеться зелений','Можна рушати, бо зараз буде зелений','Світлофор несправний — дій за знаками'],'Поєднання червоного і жовтого забороняє рух і інформує про наступне вмикання зеленого (п. 8.7.3 «є»).');
q('g30','signals','На червоному сигналі нанесена чорна контурна стрілка прямо. Що це означає?',['Рух заборонено; стрілка показує, куди можна буде їхати на зелений','Прямо можна їхати й на червоний, поступившись іншим','Прямо рух заборонено навіть на зелений'],'Чорні контурні стрілки на червоному і жовтому не змінюють значення цих сигналів, а лише показують дозволені напрямки на зелений (п. 8.7.3 «ж»).');
q('g31','signals','Горить основний червоний, а додаткова секція зі стрілкою праворуч не світиться. Чи можна повернути праворуч?',['Ні, вимкнена додаткова секція забороняє рух у її напрямку','Так, поступившись ТЗ з інших напрямків','Так, якщо немає пішоходів'],'Вимкнений сигнал додаткової секції забороняє рух у напрямку, вказаному її стрілкою (п. 8.7.3 «з»).');
q('g32','signals','Над твоєю смугою горить червоний X-подібний сигнал. Що він означає?',['Рух по цій смузі заборонено','Смуга призначена лише для маршрутних ТЗ','Попереду перехрестя рівнозначних доріг'],'Це реверсивний світлофор: червоний X-подібний сигнал забороняє, а зелена стрілка вниз дозволяє рух по смузі, над якою він розташований (п. 8.7.4).');
q('g33','signals','Над реверсивною смугою загорілася жовта стрілка, нахилена вниз праворуч. Що робиш?',['Перестроюєшся на смугу праворуч — рух цією смугою заборонено','Їдеш далі цією смугою: жовтий лише попереджає','Зупиняєшся на смузі й чекаєш зеленої стрілки'],'Жовта діагональна стрілка забороняє рух по смузі з розміткою 1.9 і інформує про зміну сигналу та потребу перестроїтися праворуч (п. 8.7.4).');
q('g34','signals','Сигнали реверсивного світлофора над смугою, позначеною з обох боків розміткою 1.9, вимкнені. Чи можна заїхати на цю смугу?',['Ні, в’їзд на неї заборонено','Так, рух нею стає двостороннім','Так, але лише для обгону'],'При вимкнених сигналах реверсивного світлофора в’їзд на смугу, позначену з обох боків розміткою 1.9, заборонено (п. 8.7.4).');
q('g35','signals','Як може виглядати спеціальний світлофор для регулювання руху трамваїв?',['Чотири біло-місячні сигнали у вигляді літери «Т»','Три жовті сигнали, розташовані вертикально','Два біло-місячні сигнали, розташовані горизонтально'],'Для трамваїв можуть застосовувати світлофори з чотирма сигналами біло-місячного кольору, розміщеними у вигляді літери «Т» (п. 8.7.5).');
q('g36','signals','У трамвайному світлофорі горять лише три верхні сигнали. Що це означає?',['Рух трамвая заборонено','Трамваю дозволено рух у всіх напрямках','Трамваю дозволено рух лише прямо'],'Рух дозволено, лише коли разом горять нижній і один чи кілька верхніх сигналів. Лише три верхні — заборона (п. 8.7.5).');
q('g37','signals','У трамвайному світлофорі горять нижній і правий верхній сигнали. Куди дозволено рух трамвая?',['Праворуч','Прямо','Ліворуч'],'Нижній сигнал разом з верхнім дозволяє рух: лівий верхній — ліворуч, середній — прямо, правий — праворуч (п. 8.7.5).');
q('g38','signals','Що означає миготливий біло-місячний сигнал світлофора на залізничному переїзді?',['Сигналізація справна і рух через переїзд не заборонено','Наближається поїзд — рух заборонено','Переїзд зачинено, треба шукати об’їзд'],'Миготливі червоні сигнали забороняють рух, а миготливий біло-місячний показує, що сигналізація справна і рух не заборонено (п. 8.7.6).');
q('g39','signals','Світлофор із силуетом пішохода горить зеленим. На кого поширюється його дія?',['Лише на пішоходів','На пішоходів і водіїв','Лише на водіїв, що повертають'],'Сигнали із силуетом пішохода стосуються лише пішоходів: зелений дозволяє їм рух, червоний забороняє (п. 8.7.7).');
q('g40','signals','Що ПДР вважають сигналами регулювальника?',['Положення корпуса і жести руками, зокрема з жезлом або диском','Лише жести жезлом, а положення корпуса значення не має','Лише сигнали свистком і вказівки через гучномовець'],'Сигнали регулювальника — положення його корпуса та жести руками, у тому числі з жезлом або диском з червоним світлоповертачем (п. 8.8).');
q('g41','signals','Для чого регулювальник подає сигнал свистком?',['Щоб привернути увагу учасників руху','Щоб дозволити рух у всіх напрямках','Щоб вимагати зупинитися конкретному авто'],'Сигнал свистком використовують для привертання уваги учасників дорожнього руху (п. 8.8).');
q('g42','signals','Регулювальник стоїть до тебе грудьми, руки витягнуті в сторони. Що це означає для тебе?',['Рух заборонено','Прямо і праворуч','Лише праворуч'],'Коли руки витягнуті в сторони чи опущені, з боку грудей і спини рух усіх ТЗ і пішоходів заборонено (п. 8.8 «а»).');
q('g43','signals','Регулювальник з опущеними руками стоїть до трамвая лівим боком. Куди дозволено рух трамвая?',['Лише прямо','Прямо і праворуч','У будь-якому напрямку'],'З лівого і правого боків регулювальника з опущеними руками трамваю можна лише прямо, нерейковим ТЗ — прямо і праворуч (п. 8.8 «а»).');
q('g44','signals','Регулювальник зігнув праву руку перед грудьми, ти — з його правого боку. Куди можна їхати легковиком?',['Прямо і праворуч','Лише праворуч','Рух заборонено'],'Права рука, зігнута перед грудьми, означає те саме, що руки в сторони: з лівого і правого боків нерейковим ТЗ — прямо і праворуч (п. 8.8 «а»).');
q('g45','signals','Регулювальник стоїть з опущеними руками. Де пішоходам дозволено переходити проїзну частину?',['За спиною і перед грудьми регулювальника','Лише за спиною регулювальника','Ніде, доки руки опущені'],'Коли руки витягнуті в сторони, опущені або права зігнута перед грудьми, пішоходи переходять за спиною та перед грудьми регулювальника (п. 8.8 «а»).');
q('g46','signals','Регулювальник витягнув праву руку вперед, ти — з його лівого боку. Куди можна їхати легковиком?',['У будь-якому напрямку','Лише ліворуч','Лише прямо і праворуч'],'З лівого боку регулювальника з витягнутою вперед правою рукою нерейковим ТЗ дозволено рух у всіх напрямках (п. 8.8 «б»).');
q('g47','signals','Права рука регулювальника витягнута вперед, трамвай — з його лівого боку. Куди можна трамваю?',['Ліворуч','Прямо','У будь-якому напрямку'],'У цьому положенні з лівого боку трамваю дозволено рух ліворуч, а нерейковим ТЗ — у всіх напрямках (п. 8.8 «б»).');
q('g48','signals','Регулювальник витягнув праву руку вперед, ти — з його правого боку. Що це означає для тебе?',['Рух заборонено','Лише праворуч','Прямо і праворуч'],'З правого боку та зі спини регулювальника з витягнутою вперед правою рукою рух усіх ТЗ заборонено (п. 8.8 «б»).');
q('g49','signals','Для чого поліцейські використовують жезл за ПДР?',['Лише для регулювання дорожнього руху','Щоб вимагати зупинки конкретного авто','Щоб показати місце для стоянки'],'Жезл використовують поліцейські та працівники військової інспекції безпеки дорожнього руху тільки для регулювання руху. Вимогу зупинитися подають іншими засобами (пп. 8.8, 8.9).');
q('g50','signals','Регулювальник подає жест, якого немає серед описаних у ПДР, але його зміст зрозумілий. Як діяти?',['Виконати: регулювальник може подавати й інші зрозумілі сигнали','Ігнорувати, бо такого сигналу в ПДР немає','Зупинитися й чекати на стандартний сигнал'],'Регулювальник може подавати інші сигнали, зрозумілі водіям і пішоходам, а його сигнали обов’язкові для виконання (пп. 8.3, 8.8).');
q('g51','signals','Поліцейське авто позаду ввімкнуло синьо-червоний маячок, з гучномовця лунає вимога зупинитися. Що робиш?',['Зупиняєшся у вказаному місці з дотриманням правил зупинки','Зупиняєшся негайно, навіть посеред смуги','Їдеш далі: зупинку можна вимагати лише жезлом'],'Вимогу зупинитися подають диском чи рукою, маячком і спецсигналом, гучномовцем або табло. Зупинятися треба у вказаному місці за правилами зупинки (п. 8.9).');
q('g52','signals','Проблисковий маячок якого кольору на поліцейському авто може означати вимогу зупинитися?',['Синього і червоного або лише червоного','Лише синього кольору','Оранжевого або жовтого'],'Вимогу про зупинку подають, зокрема, увімкненим маячком синього і червоного або лише червоного кольору та (або) спецзвуковим сигналом (п. 8.9 «б»).');
q('g53','signals','Світлофор забороняє рух. Стоп-лінії і знака «Місце зупинки» немає, перед світлофором — пішохідний перехід. Де зупинитися?',['Перед пішохідним переходом','На переході, ближче до світлофора','За переходом, перед перехрещуваною проїзною частиною'],'Без стоп-лінії і знака 5.69 на заборонний сигнал зупиняються перед світлофором чи пішохідним переходом, а якщо їх немає — перед перехрещуваною проїзною частиною (п. 8.10).');
q('g54','signals','Увімкнувся жовтий, але зупинитися перед стоп-лінією можна лише екстреним гальмуванням. Що робиш?',['Продовжуєш рух, забезпечуючи безпеку','Гальмуєш екстрено, щоб зупинитися за будь-яку ціну','Зупиняєшся за стоп-лінією посеред перехрестя'],'Якщо на жовтий чи підняту вгору руку регулювальника не зупинитися без екстреного гальмування, рух далі дозволено за умови безпеки (п. 8.11).');
q('g55','signals','Чи можна розмістити біля дороги рекламу, яку можна сплутати з дорожнім знаком?',['Ні, це заборонено','Так, якщо вона стоїть на приватній ділянці','Так, але лише поза населеними пунктами'],'Заборонено розташовувати рекламні носії та пристрої, які можна прийняти за знаки або які погіршують їх видимість чи відволікають увагу (п. 8.12).');

/* Дорожні знаки */
q('z1','signs','Що вимагає цей знак?',['Дати дорогу ТЗ, що їдуть перехрещуваною головною дорогою','Зупинитися перед перехрестям за будь-яких умов','Попереджає про перехрестя рівнозначних доріг'],'Знак 2.1 «Дати дорогу». Зупинятися не обов’язково — лише якщо інакше створиш перешкоду.','giveway');
q('z2','signs','Що вимагає цей знак?',['Зупинитися перед стоп-лінією або краєм перехрещуваної дороги і дати дорогу','Зупинитися, лише коли є інші авто','Знизити швидкість до 20 км/год'],'Знак 2.2 «Проїзд без зупинки заборонено». Зупинка обов’язкова завжди, навіть на порожній дорозі.','stop');
q('z3','signs','Що означає цей знак?',['Головна дорога — перевага на нерегульованих перехрестях','Кінець головної дороги','Попередження про небезпечний поворот'],'Знак 2.3 «Головна дорога». Ті, хто виїжджає з другорядних доріг, мають тебе пропустити.','main');
q('z4','signs','Що означає цей знак?',['Кінець головної дороги — далі переваги вже немає','Головна дорога змінює напрямок','Дорога звужується'],'Знак 2.4 «Кінець головної дороги». На наступному перехресті черговість визначай за знаками або правилом перешкоди справа.','endmain');
q('z5','signs','Що забороняє цей знак?',['В’їзд усіх ТЗ у цьому напрямку','Будь-який рух в обох напрямках','Зупинку і стоянку'],'Знак 3.21 «В’їзд заборонено». Часто стоїть на виїзді з дороги з одностороннім рухом.','noentry');
q('z6','signs','Що означає цей знак?',['Рух усіх ТЗ заборонено','Обмеження швидкості','Дорога з одностороннім рухом'],'Знак 3.1 «Рух заборонено». На відміну від «В’їзд заборонено», забороняє рух загалом.','notraffic');
q('z7','signs','Де закінчується дія цього знака, якщо немає таблички?',['На найближчому перехресті за знаком','Через 1 км','Лише біля знака кінця обмеження'],'Знак 3.29 діє до найближчого перехрестя, а в населеному пункті без перехресть — до його кінця.','speed40');
q('z8','signs','Що забороняє цей знак?',['Зупинку і стоянку','Лише стоянку','Рух усіх ТЗ'],'Знак 3.34 «Зупинку заборонено». Де заборонена зупинка, там і стоянка.','nostopping');
q('z9','signs','Що забороняє цей знак?',['Стоянку, а зупинка дозволена','Зупинку і стоянку','В’їзд'],'Знак 3.35 «Стоянку заборонено» має одну червону смугу. Дві перехрещені — «Зупинку заборонено».','noparking');
q('z10','signs','Що вимагає цей знак?',['Рухатися лише прямо','Рух прямо заборонено','Головна дорога йде прямо'],'Знак 4.1 «Рух прямо» — наказовий, синє коло.','straight');
q('z11','signs','Постійний знак і тимчасовий знак на щиті з жовтим фоном вимагають різного. Чим керуватися?',['Тимчасовим знаком','Постійним знаком','Тим, що встановлено ближче до дороги'],'Тимчасові знаки розміщують на переносних пристроях, дорожньому обладнанні або на щиті з жовтим фоном, і вони мають перевагу перед постійними (п. 8.2).');
q('z12','signs','Поза населеним пунктом знаки 1.1 «Небезпечний поворот праворуч» і 1.2 «Небезпечний поворот ліворуч» попереджають про заокруглення радіусом менше:',['500 м','300 м','150 м'],'Поза населеними пунктами — радіус менше 500 м, у населених — менше 150 м, або заокруглення з обмеженою оглядовістю (знаки 1.1, 1.2).');
q('z13','signs','Знак «Крутий спуск» попереджає про ділянку, на якій діють вимоги ПДР щодо руху:',['Гірськими дорогами і на крутих спусках','Автомагістралями і дорогами для автомобілів','У житловій і пішохідній зонах'],'Знаки 1.6 і 1.7 попереджають про підйом або спуск, на якому діють вимоги розділу 28 «Рух по гірських дорогах і на крутих спусках» (знак 1.7).');
q('z14','signs','Знак 1.8 «Виїзд на набережну або берег» стоїть із табличкою 7.11. Про що попереджають?',['Про наближення до поромної переправи','Про можливе підтоплення дороги','Про пляж поруч із дорогою'],'Знак 1.8 застосовують із табличкою 7.11 «Поромна переправа» — попереду виїзд на берег до поромної переправи (знак 1.8, табличка 7.11).');
q('z15','signs','Де, крім ділянок із буграми, напливами чи нерівними стиками мостів, можуть встановити знак 1.11 «Пагорб»?',['Перед штучною нерівністю для примусового зниження швидкості','Перед ділянкою з вибоїнами замість знака 1.12','Перед пішохідним переходом замість знака 1.32'],'Знак 1.11 ставлять і перед штучними буграми — біля небезпечних виїздів з прилеглих територій, місць інтенсивного руху дітей через дорогу тощо (знак 1.11).');
q('z16','signs','Трикутний знак 1.32 «Пішохідний перехід» попереджає про наближення до:',['Нерегульованого пішохідного переходу','Регульованого пішохідного переходу','Підземного пішохідного переходу'],'Знак 1.32 попереджає про нерегульований перехід, позначений знаками або розміткою. Самі межі переходу позначають знаки 5.38.1 і 5.38.2 (знак 1.32).');
q('z17','signs','Які попереджувальні знаки повторюють і в населених пунктах?',['«Діти» і «Дорожні роботи»','«Слизька дорога» і «Вибоїна»','«Пішохідний перехід» і «Світлофорне регулювання»'],'Поза населеними пунктами повторюють знаки 1.8, 1.13–1.16, 1.25, 1.27, 1.28, 1.33 і 1.37, а в населених — лише 1.33 і 1.37 (знаки 1.33, 1.37).');
q('z18','signs','Перед короткостроковими роботами на проїзній частині в населеному пункті знак «Дорожні роботи» можуть поставити ближче, ніж зазвичай. На якій відстані?',['10–15 м','1–5 м','25–30 м'],'Зазвичай попереджувальні знаки в населених пунктах ставлять за 50–100 м, але знак 1.37 перед короткостроковими роботами можна встановити за 10–15 м (знак 1.37).');
q('z19','signs','Який із цих попереджувальних знаків тимчасовий і стоїть лише на час робіт на дорозі?',['«Вибоїна»','«Перехрещення рівнозначних доріг»','«Пішохідний перехід»'],'Тимчасові попереджувальні знаки — 1.10, 1.12, 1.14, 1.15, 1.37 і 1.38: їх ставлять на період, потрібний для робіт на дорозі (знак 1.12).');
q('z20','signs','Що позначає знак 1.41 і що вказують таблички 7.21.1–7.21.5 під ним?',['Місце концентрації ДТП; таблички — можливий вид ДТП','Пост поліції; таблички — вид перевірки','Дорожні роботи; таблички — вид робіт'],'Знак 1.41 «Місце (ділянка) концентрації дорожньо-транспортних пригод» ставлять із табличками 7.21.1–7.21.5 «Вид небезпеки» (знак 1.41).');
q('z21','signs','Про що попереджає цей знак?',['Про аварійно небезпечну ділянку дороги','Про дорожні роботи попереду','Про слизьку дорогу'],'Знак 1.39 «Аварійно небезпечна ділянка (інша небезпека)» ставлять там, де параметри дороги не відповідають будівельним нормам (знак 1.39).','danger');
q('z22','signs','Під цим знаком табличка 7.22 «Лижники». Про що вона попереджає?',['Поруч гірськолижні траси або траси інших зимових видів спорту','Дорогу можуть переходити туристи','Рух дозволено лише з ланцюгами проти ковзання'],'Табличку 7.22 ставлять зі знаком 1.39 перед ділянками доріг поблизу гірськолижних трас або трас інших зимових видів спорту (табличка 7.22).','danger');
q('z23','signs','Про що попереджає цей знак?',['Про перехрещення рівнозначних доріг','Про залізничний переїзд без шлагбаума','Про перехрещення з другорядною дорогою'],'Знак 1.21 «Перехрещення рівнозначних доріг». На такому перехресті поступаються ТЗ, що наближаються праворуч (знак 1.21, п. 16.12).','crossroads');
q('z24','signs','Поза населеним пунктом на якій відстані до перехрестя зазвичай встановлюють цей знак?',['150–300 м','50–100 м','10–15 м'],'Попереджувальні знаки ставлять поза населеними пунктами за 150–300 м, а в населених — за 50–100 м до небезпечного місця; інша відстань вказується на табличці 7.1.1 (знак 1.21).','crossroads');
q('z25','signs','Про що попереджає цей знак?',['Про перехрестя, перехід чи ділянку, де рух регулює світлофор','Про пост регулювальника на перехресті попереду','Про пішохідний перехід, де світлофора немає'],'Знак 1.24 «Світлофорне регулювання» попереджає про перехрестя, пішохідний перехід або ділянку дороги, рух на якій регулюється світлофором (знак 1.24).','trafficlight');
